name: Remove SLO Label After SLO Workflow Completes

on:
  workflow_dispatch:
    inputs:
      prNumber:
        description: 'Pull Request number'
        required: true
        type: number

jobs:
  remove-slo-label:
    runs-on: ubuntu-latest
    needs: slo-report
    if: ${{ github.event_name == 'workflow_dispatch' }}
    steps:
      - name: Checkout repository
        uses: actions/checkout@v2

      - name: Set up Go
        uses: actions/setup-go@v2
        with:
          go-version: '1.17'

      - name: Remove SLO label
        id: remove-label
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { context } = require('@actions/github');
            const octokit = new github.getOctokit(context.repo.token);

            try {
              await octokit.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: github.context.inputs.prNumber,
                name: 'SLO',
              });
              console.log('SLO label removed successfully.');
            } catch (error) {
              if (error.status === 404) {
                console.log('SLO label not found, skipping removal.');
              } else {
                throw error;
              }
            }
